(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-periods-abbreviations":{"title":"Periods in Abbreviations","topic":"Punctuation","questions":[{"id":"punctuation-periods-abbreviations-q0001","version":4,"contentHash":"sha256:a690e1c09ad0ad7f4417b883efb86aa1e226ae4a8e7db8514a49d17bc3a8ca00","question":"Which abbreviation uses periods correctly?","choices":["Mr","Mr.","M.r.","M.r"],"correct":1,"explanation":{"correct":"Answer: Mr. Standard English abbreviations for titles like 'Mister' require a period at the end to show that it is a shortened form of the full word.","incorrect":[{"choice":"Mr","category":"missing terminal period","reason":"Omitting the period makes 'Mr' look like a complete word. The period is necessary to signal to the reader that the word has been shortened."},"",{"choice":"M.r.","category":"incorrect internal punctuation","reason":"Periods are only used to show the word has been truncated or shortened. Placing a period after the 'M' splits the abbreviation in an illogical way."},{"choice":"M.r","category":"incorrect internal punctuation","reason":"Abbreviation periods should generally follow the entire abbreviation, not sit between the individual letters unless it is a specific acronym style."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, and it often uses a period to indicate that letters have been removed.","example":"Mr. (Mister), Dr. (Doctor), Mrs. (Mistress)","strategyClue":"Look at the full word you are abbreviating and identify where the shortened version ends, then place your period only at that specific finishing point.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0002","version":4,"contentHash":"sha256:c9759085ec432439507acf18887c4e52d51cde12a62dcdfb6825bb4c2b1611b7","question":"Which is the correct way to write the abbreviation for 'Doctor'?","choices":["Dr","Dr.","D.r.","D.r"],"correct":1,"explanation":{"correct":"Answer: Dr.. Abbreviations for titles like 'Doctor' require a capital letter at the beginning and a period at the end to indicate that the word has been shortened.","incorrect":[{"choice":"Dr","category":"missing end punctuation","reason":"When shortening a word, you must include a period at the end to show it is an abbreviation. Without the period, it looks like a complete word."},"",{"choice":"D.r.","category":"incorrect internal punctuation","reason":"This adds an extra period after the 'D'. An abbreviation should only have one period at the very end unless it is a specific type of multi-part abbreviation."},{"choice":"D.r","category":"incorrect internal punctuation","reason":"The period should be at the end of the full abbreviation, not between the first and second letter. Placing it after the 'D' changes how we read the shortened form."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, usually ending with a period.","example":"Doctor -> Dr., Mister -> Mr., Street -> St.","strategyClue":"Look at the full word you are shortening and identify the first and last letters. When you combine them, ensure the period is placed only after the very last letter of the shortened form.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0003","version":4,"contentHash":"sha256:dc82d4e74567cca0f5b59d208b050136ea0834c12c05dcb5fbe16d8d8ddf397b","question":"Which abbreviation is written correctly?","choices":["Ave","Ave.","A.ve.","Av.e."],"correct":1,"explanation":{"correct":"Answer: Ave. The standard abbreviation for 'Avenue' ends with a period, which is required to show that the word has been shortened.","incorrect":[{"choice":"Ave","category":"missing punctuation","reason":"Abbreviation rules usually require a period at the end to signal that the word is shortened. Leaving it off looks like a regular, full-length word."},"",{"choice":"A.ve.","category":"incorrect period placement","reason":"You only place a period at the end of the shortened word. Adding a period after the first letter breaks the rule of abbreviating the word as a single unit."},{"choice":"Av.e.","category":"multiple periods used","reason":"This includes an extra period in the middle. We only need one period at the very end to show that the word is being cut short."}]},"studyAid":{"definition":"Abbreviations are shortened forms of words that typically end with a period to show that letters have been removed.","example":"Avenue = Ave., Doctor = Dr., Street = St.","strategyClue":"Look for the version that ends with a single period and keeps the letters of the word in their original order without extra punctuation inside.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0004","version":4,"contentHash":"sha256:26eb1942dea2592164a7753835f58b1205b264de10801a960de9b04791caec0b","question":"How should you write the abbreviation for 'et cetera' (and so forth)?","choices":["etc","etc.","e.t.c.","e.t.c"],"correct":1,"explanation":{"correct":"Answer: etc. The abbreviation for 'et cetera' is always written as 'etc.' with a period at the end because it is a shortened form of two Latin words.","incorrect":[{"choice":"etc","category":"missing terminal punctuation","reason":"This is missing the period. Abbreviations that do not end with the last letter of the full word usually require a period to show they have been shortened."},"",{"choice":"e.t.c.","category":"excessive period usage","reason":"This includes periods after every letter, but the abbreviation 'etc.' is a single unit representing two words, not a letter-by-letter acronym."},{"choice":"e.t.c","category":"improper abbreviation format","reason":"This is incorrect because it uses extra periods throughout the abbreviation and is missing the final period to mark the end of the shortened word."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, often ending with a period to show that letters have been removed.","example":"Mr. (Mister), Jan. (January), etc. (et cetera), oz. (ounce)","strategyClue":"Think about how the word looks in a dictionary or textbook; standard abbreviations follow specific, fixed spelling rules rather than placing a period after every single letter.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0005","version":4,"contentHash":"sha256:8e61373d3b9247c0865224d2e812fb3d1f52e6b3bfb5309a90f2740f18077e10","question":"Which is correct?","choices":["Jan","Jan.","J.an.","J.a.n."],"correct":1,"explanation":{"correct":"Answer: Jan. The correct way to abbreviate the month January is to use the first three letters followed by a period. A single period at the end indicates that the word has been shortened.","incorrect":[{"choice":"Jan","reason":"\"Jan\" is missing the period that this abbreviation needs."},"",{"choice":"J.an.","category":"incorrect period placement","reason":"You should not place a period after the first letter of an abbreviation unless it is part of a special format. Stick to the standard three-letter form for months."},{"choice":"J.a.n.","category":"excessive punctuation","reason":"Using a period after every letter makes the abbreviation hard to read. Only one period is needed at the end of the shortened word."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, usually ending with a period to show that letters have been left out.","example":"Jan. (January), Feb. (February), Aug. (August)","strategyClue":"Look at the standard spelling of the word and identify the common three-letter prefix, then check which option uses only one period at the very end.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0006","version":4,"contentHash":"sha256:6fcedaafcb4ae672cfbeb416f5d79fd8fa5d92482ebafa9522b7198056f23eb7","question":"Which abbreviation does NOT need a period?","choices":["Mr.","Dr.","NASA","St."],"correct":2,"explanation":{"correct":"Answer: NASA. Acronyms that are pronounced as whole words, like NASA, generally do not require periods. Abbreviations that shorten a word or title usually keep a period to show letters are missing.","incorrect":[{"choice":"Mr.","category":"title abbreviation","reason":"This is a title abbreviation. Since it replaces the full word 'Mister,' it needs a period to show the word has been shortened."},{"choice":"Dr.","category":"title abbreviation","reason":"This is a shortened form of 'Doctor.' We place a period after these types of abbreviations to indicate that letters have been removed."},"",{"choice":"St.","category":"address abbreviation","reason":"This is an abbreviation for 'Street' or 'Saint.' Because it is a truncated word, it requires a period to be punctuated correctly."}]},"studyAid":{"definition":"An abbreviation is a shortened version of a word and usually ends with a period, while an acronym is formed from the first letters of a group of words and is often written without periods.","example":"Mr. (title), St. (street), NASA (acronym), radar (acronym)","strategyClue":"Check if the abbreviation is pronounced as a single word or if it is just a shortened version of a longer, common title or noun. If you would say the full word instead of the letters, it is likely an abbreviation needing a period.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-periods-abbreviations","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0007","version":4,"contentHash":"sha256:389e2986aab70879c0c90bd778a26e5d31700345420481de3b95328255d11cfe","question":"Which is the correct abbreviation for 'United States of America' when used as an adjective?","choices":["U.S.A.","USA","U.S.","US"],"correct":2,"explanation":{"correct":"Answer: U.S. In formal writing, when the United States is used as an adjective (as in U.S. history or U.S. border), it is abbreviated with periods to represent the letters in 'United States'.","incorrect":[{"choice":"U.S.A.","category":"noun vs adjective","reason":"U.S.A. stands for the noun 'United States of America'. When functioning as an adjective, we typically use the shorter abbreviation 'U.S.' instead."},{"choice":"USA","category":"missing periods","reason":"Abbreviations for countries acting as adjectives in formal writing should include periods. Writing 'USA' without periods is more common in casual signs or addresses but less preferred in formal sentences."},"",{"choice":"US","category":"missing punctuation","reason":"When using the abbreviation as an adjective, you need the periods to show that these are abbreviations of two separate words, 'United' and 'States'."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, often ending with a period to show that letters have been omitted.","example":"U.S. senator (correct), US senator (incorrect); St. Paul (correct), St Paul (incorrect).","strategyClue":"Ask yourself if the abbreviation is replacing a noun (the country itself) or describing another word (the country's identity). Look for the standard formal punctuation style for two-word titles.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0008","version":5,"contentHash":"sha256:08118a80bba769b65242f12b894c88d6afffff88fa8ba30336e04d45249fee84","question":"Which abbreviation is incorrect?","choices":["a.m.","p.m.","A.M.","am."],"correct":3,"explanation":{"correct":"Answer: am. Standard style guides require periods after the abbreviations for ante meridiem and post meridiem to properly indicate they are shortened forms.","incorrect":[{"choice":"a.m.","category":"standard time abbreviation","reason":"This is a correct form. It includes the necessary periods to show the reader that the letters stand for the Latin phrase 'ante meridiem'."},{"choice":"p.m.","category":"standard time abbreviation","reason":"This is a correct form. Like 'a.m.', it requires periods to correctly abbreviate the Latin words for 'after noon'."},{"choice":"A.M.","category":"capitalization and punctuation","reason":"While often used in titles or headings, this is generally accepted as a valid variant. However, 'am.' lacks the required periods and follows incorrect punctuation rules for these specific abbreviations."},""]},"studyAid":{"definition":"Abbreviations for times of day should include periods to show they are shortened versions of Latin words.","example":"6:00 a.m. (correct), 6:00 am (incorrect), 4:30 p.m. (correct), 4:30 pm (incorrect)","strategyClue":"Check if the abbreviation includes periods after every letter. If an abbreviation representing a specific Latin term is missing its terminal punctuation, it is likely non-standard.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"punctuation-periods-abbreviations","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0009","version":4,"contentHash":"sha256:0316fa158cf49da5689e9a7d8e4b534ddc6c94d2ec231b5ab431b9e47ca93979","question":"How do you correctly abbreviate 'for example'?","choices":["eg","e.g.","e.g","eg."],"correct":1,"explanation":{"correct":"Answer: e.g. This abbreviation comes from the Latin phrase 'exempli gratia,' which means 'for example.' It is standard to use a period after each letter.","incorrect":[{"choice":"eg","category":"missing punctuation","reason":"Abbreviations like this need periods to show that they are shortened forms of longer words. Leaving them out makes the abbreviation look incomplete."},"",{"choice":"e.g","category":"incomplete punctuation","reason":"This option is missing the second period. Remember that each letter in the abbreviation represents a word, so both should have a period after them."},{"choice":"eg.","category":"incorrect punctuation format","reason":"This choice misses the first period. You must place a period after each letter because both 'e' and 'g' stand for separate words in the original Latin phrase."}]},"studyAid":{"definition":"Abbreviations are shortened versions of words or phrases, often using periods to signal that letters have been removed.","example":"i.e. (that is), e.g. (for example), Dr. (Doctor)","strategyClue":"Think of each letter in the abbreviation as a placeholder for a word. If you place a period after each individual letter, you will be using the correct punctuation format.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0010","version":4,"contentHash":"sha256:2a5cbe4b14188ca8d6f599c2d74cd1dcfa850f522bc4246300712ab0c32841dd","question":"Which is correct for 'Junior' when used after a name?","choices":["Jr","Jr.","J.r.","J.r"],"correct":1,"explanation":{"correct":"Answer: Jr.. When abbreviating 'Junior' after a name, the standard form includes a capital J, a lowercase r, and a period to mark it as an abbreviation.","incorrect":[{"choice":"Jr","category":"missing period","reason":"Abbreviations typically require a period at the end to show that letters have been left out. Always include the period after 'Jr'."},"",{"choice":"J.r.","category":"incorrect internal punctuation","reason":"This abbreviation only uses a period at the end. Putting a period between the J and the r treats each letter as if it were a separate abbreviation, which is incorrect."},{"choice":"J.r","category":"incorrect punctuation pattern","reason":"This choice incorrectly places a period after the 'J' instead of at the end of the full abbreviation. Standard English usage follows the 'Jr.' format."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, often ending with a period to show that it is not the complete word.","example":"Mr. (Mister), Dr. (Doctor), Jr. (Junior)","strategyClue":"Look for the version that follows standard professional formatting where the abbreviation ends with one period, rather than placing periods between the individual letters.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0011","version":4,"contentHash":"sha256:aea6bce12de0cbd3f292a81bea5bf9d39acf6e56f4e4f4a59cbe456a508296f8","question":"Which abbreviation for states is correct in formal writing?","choices":["CA","Ca","C.A.","Ca."],"correct":0,"explanation":{"correct":"Answer: CA. Formal writing requires the standard two-letter postal code abbreviation for states, which are always written in all capital letters without periods.","incorrect":["",{"choice":"Ca","category":"incorrect capitalization","reason":"State abbreviations should always be fully capitalized to be formal and standard. Using only a capital 'C' looks like a standard word rather than an official state code."},{"choice":"C.A.","category":"unnecessary punctuation","reason":"Periods are used for many abbreviations, but the official postal codes for states, like CA, are written without any periods between the letters."},{"choice":"Ca.","category":"incorrect format and punctuation","reason":"This choice incorrectly uses lowercase letters and an unnecessary period. Always use two capital letters with no punctuation for state abbreviations."}]},"studyAid":{"definition":"Official state abbreviations for addresses and formal writing consist of two capital letters with no periods or spaces.","example":"CA (California), NY (New York), TX (Texas)","strategyClue":"Check the capitalization and look for extra punctuation marks. Remember that official state codes are written in all caps with no extra dots.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0012","version":4,"contentHash":"sha256:11903c30113f14b9838ffaefc325f9c2864d7f5809a5cfa5edb380da97109ccf","question":"Which is the correct abbreviation for 'pages'?","choices":["pgs","pgs.","pp.","pp"],"correct":2,"explanation":{"correct":"Answer: pp. In standard English, the abbreviation for the plural word 'pages' is written as 'pp.' with two p's followed by a period.","incorrect":[{"choice":"pgs","category":"incorrect abbreviation","reason":"While 'pg' is sometimes used for a single page, 'pgs' is not the standard accepted abbreviation for the plural 'pages'."},{"choice":"pgs.","category":"missing proper form","reason":"Even though you remembered the period, 'pgs.' is not the dictionary-standard abbreviation for the plural word 'pages'."},"",{"choice":"pp","category":"missing punctuation","reason":"Abbreviations like this one usually require a period at the end to show that it is a shortened form of a word."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, often ending with a period to signal that letters have been removed.","example":"page = p., pages = pp., doctor = Dr., street = St.","strategyClue":"Look up the standard abbreviation in a dictionary or style guide, as plural abbreviations for common nouns often follow specific rules that differ from simply adding an 's'.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0013","version":4,"contentHash":"sha256:0a888ebd92e6ddea38c96812a725acffb5bc395a33428b541061b5f1c8a832da","question":"Which abbreviation is written correctly?","choices":["inc","Inc.","I.nc.","In.c."],"correct":1,"explanation":{"correct":"Answer: Inc. This is the standard abbreviation for 'Incorporated,' which requires a capital letter at the start and a period at the end to show that it is a shortened word.","incorrect":[{"choice":"inc","category":"missing capitalization","reason":"Abbreviated titles or business names like 'Incorporated' always start with a capital letter, just like the full word would."},"",{"choice":"I.nc.","category":"improper punctuation","reason":"You only place a period at the end of the abbreviation to show it is a shortened form. Putting a period after the first letter makes it look like two separate abbreviations."},{"choice":"In.c.","category":"improper punctuation","reason":"Placing a period in the middle of the word interrupts the abbreviation. Standard abbreviations for this term use only one period at the very end."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, usually ending with a period to signal that letters have been left out.","example":"Jan. (January), Rd. (Road), Mr. (Mister)","strategyClue":"Visualize the full word and identify which part represents the shortened version, then check for a single period at the very end and a capital letter at the start.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0014","version":4,"contentHash":"sha256:991935590a01792e47cdf5e4e52fb2d7c6ffb3972d6e9bc0f148a32cb690125a","question":"Which is the correct way to write 'approximately'?","choices":["approx","approx.","a.pprox.","appox."],"correct":1,"explanation":{"correct":"Answer: approx. The standard abbreviation for 'approximately' ends with a period to signal that it is a shortened form of a longer word.","incorrect":[{"choice":"approx","category":"missing punctuation","reason":"An abbreviation usually requires a period at the end to show that the word has been cut short. Without the period, it looks incomplete."},"",{"choice":"a.pprox.","category":"incorrect placement","reason":"Adding a period in the middle of the word 'a.pprox.' is unnecessary and confuses the reader. A period should only appear at the end of the abbreviation."},{"choice":"appox.","category":"spelling error","reason":"This choice misses the 'r' after the 'p'. Always check your spelling before adding the period to your abbreviation."}]},"studyAid":{"definition":"An abbreviation is a shortened form of a word or phrase, and it is usually followed by a period to indicate that letters have been removed.","example":"Doctor = Dr., Street = St., approximately = approx.","strategyClue":"Look closely at the spelling of the original word and identify which letters are missing. Ensure your chosen abbreviation retains the correct letters and ends with a clear punctuation mark.","link":"https://www.grammar-monster.com/glossary/abbreviation.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0015","version":4,"contentHash":"sha256:c1f67001c6ea225282af6007a15a238a879b55fe28ec47de65d738562acf619a","question":"Which sentence uses periods correctly for abbreviations and end punctuation?","choices":["Dr Lee moved to Elm Ave yesterday.","Dr. Lee moved to Elm Ave. yesterday.","Dr Lee. moved to Elm Ave. yesterday","Dr. Lee moved to Elm Ave yesterday."],"correct":1,"studyAid":{"definition":"Abbreviations are short versions of words and must end with a period to show they are not full words. Every sentence must also end with a final punctuation mark.","example":"Mr. Smith, St. (Street), Rd. (Road), Jan. (January)","strategyClue":"Scan each word that is shorter than its full meaning. Check that every shortened word has its own period, and then verify that the very last character of the entire sentence is also a period.","link":"https://www.grammar-monster.com/lessons/abbreviations_full_stops_periods.htm","linkText":"Grammar Monster - Abbreviations"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"explanation":{"correct":"Answer: Dr. Lee moved to Elm Ave. yesterday. Abbreviations like 'Dr.' and 'Ave.' require a period to indicate they are shortened words, and the sentence must also end with a final period.","incorrect":[{"choice":"Dr Lee moved to Elm Ave yesterday.","category":"missing abbreviation periods","reason":"This sentence forgets the periods after 'Dr' and 'Ave'. Because these are abbreviations, they must always have a period to show that letters are missing."},"",{"choice":"Dr Lee. moved to Elm Ave. yesterday","category":"misplaced and missing periods","reason":"The period is missing from 'Dr' and misplaced after 'Lee', which breaks up the name incorrectly. Also, every complete sentence needs a final period at the end."},{"choice":"Dr. Lee moved to Elm Ave yesterday.","category":"missing abbreviation period","reason":"While 'Dr.' is punctuated correctly, 'Ave' is missing its period. You must place a period after every abbreviation to maintain proper formal writing."}]}},{"id":"punctuation-periods-abbreviations-q0063","version":5,"contentHash":"sha256:58a5e2a73b4029c34ba066bd5610f0345107b16a8cb64d80cdc51333d7f53e58","question":"Choose the word that fits best in the blank and shows the correct punctuation. I am traveling with my middle school class to _____________ this summer.","choices":["Washington: D.","Washington, dc C. Washington dc","Washington D.C.","Washington, D.C.,"],"correct":3,"explanation":{"correct":"Answer: Washington, D.C.,. The names of cities and states (or countries) are proper nouns and must be capitalized. When a city and state (or abbreviation) are listed together, a comma must follow both the city and the abbreviation.","incorrect":[{"choice":"Washington: D.","category":"incorrect punctuation mark","reason":"A colon is used to introduce a list or a formal quote, not to separate a city from its abbreviation. Always use a comma here."},{"choice":"Washington, dc C. Washington dc","category":"capitalization and punctuation","reason":"This choice uses lowercase letters for the abbreviation and misses the necessary periods in the abbreviation. Proper nouns must always be capitalized."},{"choice":"Washington D.C.","category":"missing comma","reason":"While this capitalizes the letters correctly, it misses the required comma after the abbreviation. A comma is necessary when the location appears in the middle of a sentence."},""]},"studyAid":{"definition":"Proper nouns, such as names of specific places, must be capitalized. When you write a city and a region abbreviation together in a sentence, use a comma after the city and after the abbreviation.","example":"I visited Austin, TX, last year. We live in Chicago, IL, during the winter.","strategyClue":"Look at the abbreviation style for the place name: check for both internal periods and the specific punctuation mark that separates the city from the state abbreviation.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":63,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0068","version":4,"contentHash":"sha256:7d1a6db27eadf4bde80d90c678514899d8c5a5f0bb8c3a0b34536211ab899e68","question":"Which abbreviation is incorrect?","choices":["Minnesota – MN","Missouri – MO","Mississippi – MS","Maine – MA"],"correct":3,"explanation":{"correct":"Answer: Maine – MA. The correct two-letter abbreviation for the state of Maine is ME. MA is the abbreviation for the state of Massachusetts.","incorrect":[{"choice":"Minnesota – MN","category":"correct state abbreviation","reason":"This is correct! MN is the standard two-letter postal abbreviation for Minnesota."},{"choice":"Missouri – MO","category":"correct state abbreviation","reason":"This is correct! MO is the standard two-letter postal abbreviation for Missouri."},{"choice":"Mississippi – MS","category":"correct state abbreviation","reason":"This is correct! MS is the standard two-letter postal abbreviation for Mississippi."},""]},"studyAid":{"definition":"United States states use standardized two-letter abbreviations for postal mail and official documents.","example":"New York is NY, California is CA, and Maine is ME.","strategyClue":"Look at the first and last letters of the state name and compare them to the abbreviation provided. Note that some states share similar letters, so double-check those that start with the same sound or letter.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":68,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0083","version":5,"contentHash":"sha256:729ac96193985212fabf6380b6c208abc078fba15bce83761046e1c6a7f6c7c8","question":"Which abbreviation is incorrect?","choices":["apartment – apt.","hospital – hosp.","building bldg. –","avenue – avn."],"correct":3,"explanation":{"correct":"Answer: avenue – avn. The correct abbreviation for 'avenue' is 'ave.' or 'ave', not 'avn.'","incorrect":[{"choice":"apartment – apt.","category":"correct abbreviation","reason":"This abbreviation is actually correct! 'Apt.' is the standard way to shorten the word 'apartment'."},{"choice":"hospital – hosp.","category":"correct abbreviation","reason":"This abbreviation is actually correct! 'Hosp.' is the standard, accepted way to shorten the word 'hospital'."},{"choice":"building bldg. –","category":"correct abbreviation","reason":"This abbreviation is actually correct! 'Bldg.' is the standard, accepted way to shorten the word 'building'."},""]},"studyAid":{"definition":"Abbreviations are shortened forms of words, often used to save space in addresses or lists, and usually end with a period.","example":"street = st., doctor = dr., road = rd.","strategyClue":"Check your dictionary or look at common address abbreviations to see how words are typically shortened. Many abbreviations keep the first few letters of the word and drop the vowels near the end.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_ Proficient 2_4th grade.pdf","sourceQuestionNumber":32,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":83,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0170","version":5,"contentHash":"sha256:f0904a08a3e67ede22412e33cd7cfab5e0762ed39204ef625410ec3e19a86905","question":"Which abbreviation is incorrect?","choices":["Senior = Sr.","Drive = Dr.","Inch = In.","Cup = Cp."],"correct":3,"explanation":{"correct":"Answer: Cup = Cp. The standard abbreviation for 'cup' is 'c.', while 'cp.' is not widely recognized or used in cooking or measurements.","incorrect":[{"choice":"Senior = Sr.","category":"common title abbreviation","reason":"This is a correct abbreviation for a title. It is commonly used after a person's name to indicate they are the older version of that name."},{"choice":"Drive = Dr.","category":"address abbreviation","reason":"This is a correct abbreviation for 'Drive' when written in a street address, such as 'Main St. Dr.'"},{"choice":"Inch = In.","category":"measurement abbreviation","reason":"This is a correct abbreviation for the unit of measurement 'inch'. It is standard practice to use 'in.' in abbreviations."},""]},"studyAid":{"definition":"Abbreviations are shortened forms of words that often end with a period. Most abbreviations follow specific, widely accepted rules rather than just cutting a word short.","example":"Doctor = Dr., Street = St., Ounce = oz.","strategyClue":"Search for the word in a dictionary or a standard style guide to see if the specific short form you are looking at is the officially accepted way to shorten that word.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":170,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0185","version":5,"contentHash":"sha256:92d15bf8fd1860b6738c96a9b484f302f3480168f21a3721634c2fac5630aba6","question":"Which abbreviation is incorrect?","choices":["teaspoon = tsp.","yard = yrd.","minute = min.","gallon = gal."],"correct":1,"explanation":{"correct":"Answer: yard = yrd. The correct abbreviation for yard is 'yd.' or 'yd'. Adding an 'r' makes it incorrect.","incorrect":[{"choice":"teaspoon = tsp.","category":"common unit abbreviation","reason":"This is a correct abbreviation. We use 'tsp.' to represent the unit teaspoon in cooking and science."},"",{"choice":"minute = min.","category":"common unit abbreviation","reason":"This is a correct abbreviation. 'min.' is the standard way to shorten the word minute."},{"choice":"gallon = gal.","category":"common unit abbreviation","reason":"This is a correct abbreviation. 'gal.' is the accepted way to abbreviate the measurement gallon."}]},"studyAid":{"definition":"Abbreviations are shortened forms of words that often end with a period. It is important to memorize standard abbreviations because they do not always use the same letters as the full word.","example":"inch = in., foot = ft., pound = lb.","strategyClue":"Look up each abbreviation in a dictionary or your textbook. If the shortened version does not match the standard abbreviation used in measurement charts, it is likely incorrect.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Advanced 2_4th grade.pdf","sourceQuestionNumber":32,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":185,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0221","version":5,"contentHash":"sha256:71604a1b011e061f04da036ff1e6d06ca82455a1f20d22efc5b0b0eb16243453","question":"Identify which of the following statements would be formal language.","choices":["That’s sweet.","The scheduled time for the appointment is 1:00 p.m.","Sure, I guess.","Hey, what’s up?"],"correct":1,"explanation":{"correct":"Answer: The scheduled time for the appointment is 1:00 p.m. Formal language uses complete sentences, standard grammar, and avoids contractions or slang, which makes this the most professional option.","incorrect":[{"choice":"That’s sweet.","category":"contraction and slang","reason":"This phrase uses a contraction ('That's') and a slang adjective ('sweet'), which are better suited for casual conversations with friends rather than formal writing."},"",{"choice":"Sure, I guess.","category":"informal phrasing","reason":"This uses 'Sure' and 'I guess' as fillers. Formal language avoids casual, uncertain filler words and expresses ideas directly and clearly."},{"choice":"Hey, what’s up?","category":"slang and greeting","reason":"This is a casual greeting using 'Hey' and a contraction. Formal language avoids greetings and slang that would not be appropriate for professional settings."}]},"studyAid":{"definition":"Formal language is used for professional or academic situations, requiring complete sentences and avoiding contractions, slang, and casual greetings.","example":"Informal: 'It's gonna rain.' / Formal: 'It is going to rain.' | Informal: 'What's up?' / Formal: 'How are you?'","strategyClue":"Check for contractions like 'it's' or 'can't', and look for slang words or casual greetings. A formal sentence will sound like it could be read in a textbook or heard in a serious professional meeting.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":221,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0266","version":5,"contentHash":"sha256:95d56cd4af074b3b90202a472ac8672cf8570210fb74bf94acb91c12b38f66c8","question":"Choose the best way write the und erlined portion the sentence. the underlined part to of If is correct, cho ose “Correct as is.” I asked Doctor Brown about the acc ident, but he ha d no t heard about it.","choices":["I asked doctor Brown","I asked Doctor Brown, MD","I asked dr. Brown","Correct as is"],"correct":3,"explanation":{"correct":"Answer: Correct as is. Titles like 'Doctor' are capitalized when they are used as part of a person's name, and 'Brown' is a proper noun that should always be capitalized.","incorrect":[{"choice":"I asked doctor Brown","category":"capitalization error","reason":"When 'Doctor' is used as a title before a name, it must be capitalized. Leaving it as lowercase 'doctor' is incorrect because it is part of the person's proper name."},{"choice":"I asked Doctor Brown, MD","category":"unnecessary information","reason":"While 'MD' is a real title, the original sentence did not include it. Adding extra information that isn't in the original sentence makes this choice incorrect."},{"choice":"I asked dr. Brown","category":"improper abbreviation","reason":"Abbreviations for titles, such as 'dr.', should still be capitalized as 'Dr.' when they are used as part of a proper name. Using lowercase is a capitalization error."},""]},"studyAid":{"definition":"Capitalize titles like Doctor, President, or Mayor when they appear immediately before a person's name.","example":"Doctor Smith went home. (Correct) / The doctor went home. (Correct - 'doctor' is a general noun here) / doctor Smith went home. (Incorrect)","strategyClue":"Check if the title is being used as a name for a specific person. If it is attached to a name, look for both the capital letter at the start of the title and the capital letter at the start of the name.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":11,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":266,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0272","version":5,"contentHash":"sha256:17e0823d656ff582cae1c148e29728ffba2b8273622d5bb60b6eae0ebf9503e7","question":"Which abbreviation is inc orrect?","choices":["Thurs.","Sun.","Fri.","Weds."],"correct":3,"explanation":{"correct":"Answer: Weds. The standard abbreviation for Wednesday is 'Wed.' Adding an 's' at the end is incorrect because it is not part of the established abbreviation for this day of the week.","incorrect":[{"choice":"Thurs.","category":"valid day abbreviation","reason":"This is the accepted, standard abbreviation for Thursday. It is correctly spelled and punctuated with a period."},{"choice":"Sun.","category":"valid day abbreviation","reason":"This is the accepted, standard abbreviation for Sunday. It is correctly spelled and punctuated with a period."},{"choice":"Fri.","category":"valid day abbreviation","reason":"This is the accepted, standard abbreviation for Friday. It is correctly spelled and punctuated with a period."},""]},"studyAid":{"definition":"Most days of the week are abbreviated using their first three letters followed by a period. However, Wednesday is an exception that is typically abbreviated simply as 'Wed.'","example":"Mon. (Monday), Tue. (Tuesday), Wed. (Wednesday), Thu. or Thurs. (Thursday)","strategyClue":"Compare the abbreviations to the full names of the days. Look for the version that includes an extra letter that does not appear in the standard shortened form of the day.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":17,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":272,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-periods-abbreviations-q0287","version":5,"contentHash":"sha256:c5e1906e9b1a7db56ece00b67dc6c50d94696eaddc3b3d177b0da52dae21d5e7","question":"Which abbreviation is inc orrect?","choices":["Mar.","Sep.","Feb.","Nov."],"correct":1,"explanation":{"correct":"Answer: Sep. Actually, this question contains a trick; while 'Sep.' is a common abbreviation, the standard formal abbreviation for September is 'Sept.' to distinguish it clearly from the others.","incorrect":[{"choice":"Mar.","category":"standard month abbreviation","reason":"Mar. is the widely accepted and standard three-letter abbreviation for March. It is correctly punctuated with a period."},"",{"choice":"Feb.","category":"standard month abbreviation","reason":"Feb. is the correct and standard abbreviation for February. It follows the pattern of using the first three letters followed by a period."},{"choice":"Nov.","category":"standard month abbreviation","reason":"Nov. is the correct and standard abbreviation for November. It is universally accepted in formal writing."}]},"studyAid":{"definition":"Months of the year are abbreviated by using their first three or four letters followed by a period.","example":"Jan. (January), Feb. (February), Sept. (September), Oct. (October)","strategyClue":"Look for the month name that typically requires four letters instead of three to be clear and distinct from other words.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-periods-abbreviations","sourceFile":"Language Usage_Basic 2_4th grade.pdf","sourceQuestionNumber":32,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":287,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
